import{_ as o,o as r,c as e,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2019-09-11:: Ceph Orchestration Meeting","description":"","frontmatter":{"title":"2019-09-11:: Ceph Orchestration Meeting","date":"2019-09-11T00:00:00.000Z","updated":"2019-09-21T00:00:00.000Z","tags":["Ceph","Orchestrator","Device Management","Completion Implementation","Dashboard Locking Mechanism"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-09-11_-_-_Ceph_Orchestration_Meeting.md","filePath":"posts/2019/2019-09-11_-_-_Ceph_Orchestration_Meeting.md","lastUpdated":1780460162000}'),l={name:"posts/2019/2019-09-11_-_-_Ceph_Orchestration_Meeting.md"};function s(a,t,n,p,_,g){return r(),e("div",null,[...t[0]||(t[0]=[i("<p><strong>会议纪要</strong></p><p><strong>会议时间</strong>： [请填写具体日期和时间]</p><p><strong>参会人员</strong>： [请填写参会人员名单]</p><p><strong>会议主题</strong>：</p><ul><li>Ceph集群中设备管理及Orchestrator模块的优化</li><li>完成项（Completion）的实现和改进</li><li>Dashboard的锁机制</li><li>Rook模块的性能问题</li><li>Dashboard的分页功能</li></ul><p><strong>会议内容</strong>：</p><p><strong>一、设备管理</strong></p><ul><li>讨论如何通过Orchestrator模块实现设备管理，包括创建新的OSD。</li><li>确定了从简单设备组开始，逐步过渡到更复杂的设备组的策略。</li><li>计划实现从单个设备创建OSD的功能，并考虑支持多选设备创建多个OSD。</li><li>强调了确保设备可用性的重要性。</li></ul><p><strong>二、完成项（Completion）实现</strong></p><ul><li>讨论了Ceph中完成项的改进，包括合并读取和写入完成项，使用统一的完成项类。</li><li>引入了新的完成项结构，其中完成项在获得结果后立即完成，但进度引用（Progress Reference）会保持活跃，直到OSD实际创建完成。</li><li>讨论了使用进度引用进行锁定的必要性，以避免在Dashboard中同时执行多个OSD创建操作。</li></ul><p><strong>三、Dashboard的锁机制</strong></p><ul><li>讨论了在Dashboard中实现锁机制的必要性，以避免同时进行多个系统更改操作。</li><li>确定了一种基于进度引用的锁定策略，用于在Dashboard中阻止创建新的OSD，直到当前操作完成。</li><li>讨论了不同Orchestrator模块中锁定机制可能存在的差异，并计划在Orchestrator中实现通用的锁定机制。</li></ul><p><strong>四、Rook模块性能问题</strong></p><ul><li>讨论了Rook模块的性能问题，并确认引入事件监听器后性能问题已基本解决。</li></ul><p><strong>五、Dashboard分页功能</strong></p><ul><li>讨论了Dashboard中可能需要添加分页功能。</li></ul><p><strong>行动计划</strong>：</p><ul><li>实现从单个设备创建OSD的功能。</li><li>优化完成项结构，并实现基于进度引用的锁定机制。</li><li>在Orchestrator中实现通用的锁定机制。</li><li>在Dashboard中实现分页功能。</li><li>查看和修复Rook模块中存在的问题。</li><li>根据需要添加Dashboard的分页功能。</li></ul><p><strong>备注</strong>：</p><ul><li>部分内容涉及Ceph相关领域英文原文，如“Completion”、“Progress Reference”、“Orchestrator”等。</li><li>会议中提到的“Kiva”和“Brooke”可能是项目或模块的名称，具体含义需要根据实际情况进行解释。</li><li>讨论了环境变量的问题，并决定在Rook模块中修复相关问题。</li></ul>",20)])])}const d=o(l,[["render",s]]);export{c as __pageData,d as default};
